const { callClaude, validateConfig } = require('../lib/ai/claude.js')
const { getUserFromAuthHeader } = require('../lib/supabase/auth.js')
const { getSupabaseAdmin } = require('../lib/supabase/admin.js')
const { AIError, AIConfigError, AIRateLimitError, AITimeoutError, getErrorCode, getErrorStatus } = require('../lib/ai/errors.js')

const { rateLimitCount: RATE_LIMIT_COUNT, rateLimitWindowMs: RATE_LIMIT_WINDOW_MS } = require('../lib/ai/config.js')

async function checkRateLimit(userId) {
  const admin = getSupabaseAdmin()
  if (!admin) return { allowed: true }

const now = new Date().toISOString()
const { data } = await admin
  .from('ai_rate_limits')
  .select('count, window_start')
  .eq('user_id', userId)
  .maybeSingle()
if (!data) {
  await admin.from('ai_rate_limits').insert({ user_id: userId, count: 1, window_start: now })
  return { allowed: true }
}

  const windowStart = new Date(data.window_start).getTime()
  if (Date.now() - windowStart > RATE_LIMIT_WINDOW_MS) {
    await admin.from('ai_rate_limits').update({ count: 1, window_start: now }).eq('user_id', userId)
    return { allowed: true }
  }
  if (data.count >= RATE_LIMIT_COUNT) return { allowed: false }
  await admin.from('ai_rate_limits').update({ count: data.count + 1 }).eq('user_id', userId)
  return { allowed: true }
}

module.exports = async function handler(req, res) {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' })
    return
  }

const configCheck = validateConfig()
if (!configCheck.valid) {
  res.status(503).json({ error: 'IA no configurada', code: 'NOT_CONFIGURED', missing: configCheck.missing })
  return
}

const apiKey = process.env.MEAI_API_KEY
const user = await getUserFromAuthHeader(req.headers.authorization)
if (!user) {
  res.status(401).json({ error: 'No autorizado', code: 'UNAUTHORIZED' })
  return
}

const { prompt, systemPrompt, task, stream, maxTokens, temperature, responseFormat } = req.body || {}
if (!prompt?.trim()) {
  res.status(400).json({ error: 'Falta el prompt', code: 'VALIDATION_ERROR', field: 'prompt' })
  return
}

const rl = await checkRateLimit(user.id)
if (!rl.allowed) {
  res.status(429).json({ error: 'Límite de peticiones excedido. Intenta en un minuto.', code: 'RATE_LIMITED', retryAfter: 60 })
  return
}

try {
  const result = await callClaude({
    prompt,
    systemPrompt,
    apiKey,
    maxTokens,
    temperature,
    stream,
    responseFormat,
    onChunk: stream ? (chunk) => {
      res.write(`data: ${JSON.stringify({ chunk })}\n\n`)
    } : undefined,
  })

  if (stream) {
    res.write(`data: ${JSON.stringify({ done: true, usage: result.usage })}\n\n`)
    res.end()
    return
  }

  console.log(`[AI] user=${user.id} task=${task || 'unknown'} chars=${prompt.length} ok=true`)
  res.status(200).json({ text: result.text, usage: result.usage })
} catch (e) {
  console.error(`[AI] user=${user.id} error=${e?.message || 'unknown'} code=${getErrorCode(e)}`)

    const status = getErrorStatus(e)
    const code = getErrorCode(e)
    res.status(status).json({ error: e.message, code, ...(e.details || {}) })
  }
}

import { serverSignIn } from '../../lib/supabase/serverLogin.js'

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' })
    return
  }

  try {
    const { email, password } = req.body || {}
    if (!email || !password) {
      res.status(400).json({ error: 'Correo y contraseña requeridos' })
      return
    }

    const data = await serverSignIn(email, password)
    res.status(200).json({
      access_token: data.session.access_token,
      refresh_token: data.session.refresh_token,
      expires_at: data.session.expires_at,
      user: data.user,
    })
  } catch (e) {
    const msg = (e?.message || '').toLowerCase()
    if (msg.includes('invalid login') || msg.includes('invalid_credentials')) {
      res.status(401).json({ error: 'Correo o contraseña incorrectos.' })
      return
    }
    res.status(500).json({ error: e?.message || 'Error al iniciar sesión' })
  }
}

import { sendNotificationEmail, isResendConfigured } from '../../lib/email/resend.js'
import { verifyEmailRecipient } from '../../lib/email/auth.js'

const ALLOWED_TYPES = new Set(['welcome', 'project_ready', 'recording_ready', 'live_started'])

function isValidEmail(email) {
  return typeof email === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    res.status(405).json({ error: 'Method not allowed' })
    return
  }

  if (!isResendConfigured()) {
    res.status(503).json({ error: 'Email no configurado. Añade RESEND_API_KEY en Vercel.' })
    return
  }

  const { type, to, data } = req.body || {}

  if (!type || !ALLOWED_TYPES.has(type)) {
    res.status(400).json({ error: 'Tipo de notificación inválido' })
    return
  }

  if (!isValidEmail(to)) {
    res.status(400).json({ error: 'Correo inválido' })
    return
  }

  const auth = await verifyEmailRecipient(req.headers.authorization, to)
  if (!auth.ok) {
    res.status(403).json({ error: auth.error })
    return
  }

  try {
    const result = await sendNotificationEmail({ type, to, data: data || {} })
    res.status(200).json({ ok: true, id: result.id })
  } catch (e) {
    res.status(500).json({ error: e.message || 'Error al enviar email' })
  }
}

