  return {
    uploadId: upload.id,
    uploadUrl: upload.url,
  }
}

export async function getUpload(uploadId) {
  const mux = getMux()
  if (!mux) throw new Error('Mux no configurado')
  return mux.video.uploads.retrieve(uploadId)
}

export async function getAsset(assetId) {
  const mux = getMux()
  if (!mux) throw new Error('Mux no configurado')
  return mux.video.assets.retrieve(assetId)
}

export function getMp4Url(playbackId) {
  return `https://stream.mux.com/${playbackId}/high.mp4`
}

const RESTREAM_API = 'https://api.restream.io/v2'

export function isRestreamConfigured() {
  return !!process.env.RESTREAM_API_TOKEN
}

async function restreamFetch(path) {
  const token = process.env.RESTREAM_API_TOKEN
  if (!token) throw new Error('Restream no configurado')

  const res = await fetch(`${RESTREAM_API}${path}`, {
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/json',
    },
  })

  if (!res.ok) {
    const err = await res.text().catch(() => '')
    throw new Error(err || `Restream API ${res.status}`)
  }

  return res.json()
}

export async function getRestreamIngest() {
  const data = await restreamFetch('/user/channel')
  const streamKey = data?.streamKey || data?.stream_key || data?.key
  if (!streamKey) throw new Error('No se pudo obtener la stream key de Restream')

  return {
    rtmpUrl: 'rtmp://live.restream.io/live',
    streamKey,
    fullRtmpUrl: `rtmp://live.restream.io/live/${streamKey}`,
  }
}

export async function getRestreamChannels() {
  try {
    const data = await restreamFetch('/user/channels')
    const list = Array.isArray(data) ? data : data?.channels || data?.data || []
    return list.map((ch) => ({
      id: ch.id || ch.channelId,
      platform: ch.platform || ch.type || ch.name,
      name: ch.name || ch.title || ch.platform,
      enabled: ch.enabled !== false,
    }))
  } catch {
    return []
  }
}

import { createClient } from '@supabase/supabase-js'

function getSupabaseUrl() {
  return process.env.VITE_SUPABASE_URL || process.env.SUPABASE_URL || ''
}

export function isSupabaseAdminConfigured() {
  return !!getSupabaseUrl() && !!process.env.SUPABASE_SERVICE_ROLE_KEY
}

export function getSupabaseAdmin() {
  const url = getSupabaseUrl()
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY
  if (!url || !key) return null
  return createClient(url, key, {
    auth: { autoRefreshToken: false, persistSession: false },
  })
}

import { createClient } from '@supabase/supabase-js'

function getSupabaseAnon() {
  const url = process.env.VITE_SUPABASE_URL || process.env.SUPABASE_URL
  const key = process.env.VITE_SUPABASE_ANON_KEY || process.env.SUPABASE_ANON_KEY
  if (!url || !key) return null
  return createClient(url, key, {
    auth: { autoRefreshToken: false, persistSession: false },
  })
}

export async function getUserFromAuthHeader(authHeader) {
  if (!authHeader?.startsWith('Bearer ')) return null
  const token = authHeader.slice(7)
  const supabase = getSupabaseAnon()
  if (!supabase) return null
  const { data: { user }, error } = await supabase.auth.getUser(token)
  if (error || !user) return null
  return user
}

import { createClient } from '@supabase/supabase-js'

function getSupabaseAuthClient() {
  const url = process.env.VITE_SUPABASE_URL || process.env.SUPABASE_URL
  const anon = process.env.VITE_SUPABASE_ANON_KEY || process.env.SUPABASE_ANON_KEY
  if (!url || !anon) return null
  return createClient(url, anon, {
    auth: { persistSession: false, autoRefreshToken: false },
  })
}

function normalizeEmail(email) {
  const e = (email || '').trim().toLowerCase()
  return TYPO_MAP[e] || e
}

/** Login con variables de servidor (Vercel). */
export async function serverSignIn(email, password) {
  const supabase = getSupabaseAuthClient()
  if (!supabase) throw new Error('Supabase no configurado en servidor')
  const loginEmail = normalizeEmail(email)
  const { data, error } = await supabase.auth.signInWithPassword({ email: loginEmail, password })
  if (error) throw error
  if (!data?.session?.user) throw new Error('No se pudo iniciar sesión')
  return data
}

export function getSupabaseProjectRef() {
  const url = process.env.VITE_SUPABASE_URL || process.env.SUPABASE_URL || ''
  const match = url.match(/https:\/\/([a-z0-9]+)\.supabase\.co/)
  return match?.[1] || null
}

export function isYouTubeConfigured() {
  return !!(process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET)
}

export function getYouTubeAuthUrl(state) {
  const params = new URLSearchParams({
    client_id: process.env.GOOGLE_CLIENT_ID,
    redirect_uri: `${getSiteUrl()}/api/youtube/callback`,
    response_type: 'code',
    scope: YOUTUBE_SCOPES,
    access_type: 'offline',
    prompt: 'consent',
    state,
  })
  return `${GOOGLE_AUTH}?${params}`
}

export async function exchangeYouTubeCode(code) {
  const res = await fetch(GOOGLE_TOKEN, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      code,
      client_id: process.env.GOOGLE_CLIENT_ID,
      client_secret: process.env.GOOGLE_CLIENT_SECRET,
      redirect_uri: `${getSiteUrl()}/api/youtube/callback`,
      grant_type: 'authorization_code',
    }),
  })

  const data = await res.json()
  if (!res.ok) throw new Error(data.error_description || data.error || 'OAuth falló')
  return data
}

export async function refreshYouTubeToken(refreshToken) {
  const res = await fetch(GOOGLE_TOKEN, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      refresh_token: refreshToken,
      client_id: process.env.GOOGLE_CLIENT_ID,
      client_secret: process.env.GOOGLE_CLIENT_SECRET,
      grant_type: 'refresh_token',
    }),
  })

  const data = await res.json()
  if (!res.ok) throw new Error(data.error_description || 'No se pudo renovar token')
  return data
}

export async function getYouTubeChannel(accessToken) {
  const res = await fetch(`${YOUTUBE_API}/channels?part=snippet&mine=true`, {
    headers: { Authorization: `Bearer ${accessToken}` },
  })
  const data = await res.json()
  if (!res.ok) throw new Error(data.error?.message || 'Canal no encontrado')

  const ch = data.items?.[0]
  return ch ? { id: ch.id, title: ch.snippet?.title } : null
}

export async function uploadVideoToYouTube({ accessToken, title, description, videoBuffer, mimeType = 'video/mp4' }) {
  const metadata = {
    snippet: { title, description: description || '', categoryId: '22' },
    status: { privacyStatus: 'private', selfDeclaredMadeForKids: false },
  }

const initRes = await fetch(
  `${YOUTUBE_UPLOAD}?uploadType=resumable&part=snippet,status`,
  {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json; charset=UTF-8',
      'X-Upload-Content-Type': mimeType,
      'X-Upload-Content-Length': String(videoBuffer.byteLength),
    },
    body: JSON.stringify(metadata),
  },
)

if (!initRes.ok) {

  const err = await initRes.json().catch(() => ({}))
  throw new Error(err.error?.message || 'No se pudo iniciar subida a YouTube')
}

const uploadUrl = initRes.headers.get('location')
if (!uploadUrl) throw new Error('YouTube no devolvió URL de subida')

const uploadRes = await fetch(uploadUrl, {
  method: 'PUT',
  headers: {
    'Content-Type': mimeType,
    'Content-Length': String(videoBuffer.byteLength),
  },
  body: videoBuffer,
})

if (!uploadRes.ok) {

    const err = await uploadRes.text().catch(() => '')
    throw new Error(err || 'Error al subir video a YouTube')
  }

  return uploadRes.json()
}

