        <span style={{ fontSize: 10, color: '#2a2a3e' }}>Sin señal</span>
      </div>
    )
  }

  return (
    <video
      ref={videoRef}
      autoPlay
      playsInline
      muted={muted}
      className={className}
      style={{ objectFit: 'cover', width: '100%', height: '100%', ...style }}
      onClick={onClick}
    />

