import React, { useEffect, useRef, useState } from 'react'
import styles from './VUMeter.module.css'

export default function VUMeter({ level = 0, bars = 16 }) {
  const [levels, setLevels] = useState(Array(bars).fill(0))

  useEffect(() => {
    setLevels(prev => prev.map((_, i) => {
      const base = level * (1 - i * 0.04)
      return Math.max(0, Math.min(100, base + (Math.random() - 0.5) * 15))
    }))
  }, [level, bars])

  return (
    <div className={styles.meter}>
      {levels.map((lv, i) => (
        <div key={i} className={styles.bar} style={{ height: `${Math.max(8, lv)}%` }}
          data-warn={lv > 75 ? 'true' : undefined}
          data-clip={lv > 90 ? 'true' : undefined}
        />
      ))}
    </div>
  )
}

.meter {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 32px;
  width: 100%;
}
.bar {
  flex: 1;
  border-radius: 2px;
  background: var(--green);
  transition: height 0.08s ease;
  min-height: 8%;
}
.bar[data-warn='true'] { background: #BA7517; }
.bar[data-clip='true'] { background: var(--red); }

export function getBackgroundTemplate(id) {
  return BACKGROUND_TEMPLATES.find(t => t.id === id) || BACKGROUND_TEMPLATES[0]
}

export function getBackgroundCameraRect(templateId, scalePct = 100) {
  const t = getBackgroundTemplate(templateId)
  const cam = t.camera || FULL_CAM
  const scale = Math.max(70, Math.min(130, scalePct)) / 100
  const w = Math.min(100, cam.width * scale)
  const h = Math.min(100, cam.height * scale)

  const left = cam.left + (cam.width - w) / 2
  const top = cam.top + (cam.height - h) / 2
  return { top, left, width: w, height: h }
}

