export function filterManualSections(query) {
  const q = (query || '').trim().toLowerCase()
  if (!q) return MANUAL_SECTIONS
  return MANUAL_SECTIONS.filter((s) => {
    const hay = [
      s.title,
      s.summary,
      s.tip,
      ...(s.steps || []).flatMap((st) => [st.action, st.detail]),
    ].join(' ').toLowerCase()
    return hay.includes(q)
  })
}

