export function applyAIProducerPlan(project, plan) {
  if (!plan) return project
  const next = { ...project, aiPlan: plan, aiPlanAt: Date.now() }
  next.cintillos = { ...(project.cintillos || {}), ...(plan.cintillos || {}) }
  if (plan.teleprompterScript && !project.teleprompterScript?.trim()) {
    next.teleprompterScript = plan.teleprompterScript
  }
  if (plan.genre) next.podcastGenre = plan.genre
  if (plan.musicTrackId) next.musicTrackId = plan.musicTrackId
  if (plan.musicVolume != null) next.musicVolume = plan.musicVolume
  if (plan.subtitlesEnabled != null) next.subtitlesEnabled = plan.subtitlesEnabled
  if (plan.subtitleLanguage) next.subtitleLanguage = plan.subtitleLanguage
  if (plan.directorMode) next.directorMode = plan.directorMode
  if (plan.autoCintillos != null) next.autoCintillos = plan.autoCintillos
  if (plan.cintilloRotation) next.cintilloRotation = plan.cintilloRotation
  return next
}

export function useAIProducer({ analyzeEventWithAI, aiConfigured }) {
  const ranRef = useRef(false)

  const runProducer = useCallback(async (project) => {
    if (!aiConfigured || !project) return { project, plan: null, status: 'sin_ia' }
    if (project.aiPlan?.producerSummary && project.aiPlanAt) {
      return { project, plan: project.aiPlan, status: 'cached' }
    }
    const plan = await analyzeEventWithAI(project)
    if (!plan) return { project, plan: null, status: 'error' }

  const enriched = applyAIProducerPlan(project, plan)
  const music = resolveMusicTrack(plan.musicTrackId, plan.genre)
  return {
    project: enriched,
    plan,
    music,
    status: 'ready',
  }
}, [analyzeEventWithAI, aiConfigured])

  const shouldAutoRun = useCallback((project) => {
    if (!aiConfigured || ranRef.current) return false
    if (!project?.episodeTitle && !project?.name) return false
    return !project.aiPlan?.producerSummary
  }, [aiConfigured])

  const markRan = useCallback(() => { ranRef.current = true }, [])

  return { runProducer, shouldAutoRun, markRan }
}

import { useRef, useCallback, useEffect } from 'react'

export function useAudioMix() {
  const ctxRef = useRef(null)
  const destRef = useRef(null)
  const micSourceRef = useRef(null)
  const musicSourceRef = useRef(null)
  const musicGainRef = useRef(null)
  const micGainRef = useRef(null)

  useEffect(() => () => {
    ctxRef.current?.close().catch(() => {})
  }, [])

const ensureContext = useCallback(() => {
  if (!ctxRef.current) {
    ctxRef.current = new AudioContext()
    destRef.current = ctxRef.current.createMediaStreamDestination()
    micGainRef.current = ctxRef.current.createGain()
    micGainRef.current.gain.value = 1
    micGainRef.current.connect(destRef.current)
    musicGainRef.current = ctxRef.current.createGain()
    musicGainRef.current.gain.value = 0
    musicGainRef.current.connect(destRef.current)
  }
  return { ctx: ctxRef.current, dest: destRef.current }
}, [])

const setMicStream = useCallback((micStream) => {
  const { ctx } = ensureContext()
  if (micSourceRef.current) {
    try { micSourceRef.current.disconnect() } catch { /* */ }
    micSourceRef.current = null
  }
  if (!micStream) return
  const src = ctx.createMediaStreamSource(micStream)
  src.connect(micGainRef.current)
  micSourceRef.current = src
}, [ensureContext])

const setMusicMix = useCallback(({ musicEl, volume = 30, playing = false }) => {
  const { ctx } = ensureContext()
  if (musicSourceRef.current) {
    try { musicSourceRef.current.disconnect() } catch { /* */ }
    musicSourceRef.current = null
  }

  if (musicGainRef.current) {
    musicGainRef.current.gain.value = playing ? volume / 100 : 0
  }

  if (!musicEl || !playing || typeof musicEl.captureStream !== 'function') return

  const captured = musicEl.captureStream()
  const track = captured.getAudioTracks()[0]
  if (!track) return

  const src = ctx.createMediaStreamSource(new MediaStream([track]))
  src.connect(musicGainRef.current)
  musicSourceRef.current = src
}, [ensureContext])

const buildRecordingStream = useCallback(async (videoStream, { micStream, musicEl, musicVolume, musicPlaying }) => {
  const { ctx, dest } = ensureContext()
  if (ctx.state === 'suspended') await ctx.resume()

  setMicStream(micStream)
  setMusicMix({ musicEl, volume: musicVolume, playing: musicPlaying })

    const audioTracks = dest.stream.getAudioTracks()
    const tracks = [
      ...videoStream.getVideoTracks(),
      ...(audioTracks.length ? audioTracks : (micStream?.getAudioTracks() || [])),
    ]
    return new MediaStream(tracks)
  }, [ensureContext, setMicStream, setMusicMix])

  return { setMicStream, setMusicMix, buildRecordingStream }
}

import { useEffect } from 'react'

export function useAutoSwitcher({
  enabled,
  intervalSec = 8,
  streams,
  activeCamera,
  setActiveCamera,
  onlyWhileRecording = false,
  recording = false,
}) {
  useEffect(() => {
    if (!enabled) return
    if (onlyWhileRecording && !recording) return

    const slots = [0, 1, 2].filter(i => streams[i])
    if (slots.length < 2) return

    const id = setInterval(() => {
      setActiveCamera(prev => {
        const current = prev ?? slots[0]
        const idx = slots.indexOf(current)
        const nextIdx = idx === -1 ? 0 : (idx + 1) % slots.length
        return slots[nextIdx]
      })
    }, intervalSec * 1000)

    return () => clearInterval(id)
  }, [enabled, intervalSec, streams, setActiveCamera, onlyWhileRecording, recording])
}

