export function useTeleprompter(initialScript = '', autoScrollWithRecord = true) {
  const [script, setScript] = useState(initialScript)
  const [playing, setPlaying] = useState(false)
  const [speed, setSpeed] = useState(35)
  const [fontSize, setFontSize] = useState(28)
  const [mirror, setMirror] = useState(false)
  const [direction, setDirection] = useState('up')
  const [offset, setOffset] = useState(0)
  const [visible, setVisible] = useState(false)
  const [maxScroll, setMaxScroll] = useState(0)

const rafRef = useRef(null)
const lastRef = useRef(0)
const playingRef = useRef(false)

useEffect(() => {
  playingRef.current = playing
}, [playing])

useEffect(() => {
  if (initialScript) setScript(initialScript)
}, [initialScript])

useEffect(() => {
  if (maxScroll > 0) {
    setOffset(o => Math.min(o, maxScroll))
  }
}, [maxScroll])

const tick = useCallback((ts) => {
  if (!playingRef.current) return
  if (!lastRef.current) lastRef.current = ts
  const dt = (ts - lastRef.current) / 1000
  lastRef.current = ts
  setOffset(o => {
    const next = o + speed * dt
    if (maxScroll > 0 && next >= maxScroll) {
      playingRef.current = false
      setPlaying(false)
      return maxScroll
    }
    return next
  })
  rafRef.current = requestAnimationFrame(tick)
}, [speed, maxScroll])

useEffect(() => {
  if (!playing) {
    if (rafRef.current) cancelAnimationFrame(rafRef.current)
    lastRef.current = 0
    return undefined
  }
  rafRef.current = requestAnimationFrame(tick)
  return () => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current)
  }
}, [playing, tick])

  const toggle = useCallback(() => setPlaying(p => !p), [])
  const reset = useCallback(() => { setOffset(0); setPlaying(false) }, [])

  const setRecordingActive = useCallback((active) => {
    if (!autoScrollWithRecord) return
    if (active) {
      setVisible(true)
      setOffset(0)
      setPlaying(true)
    } else {
      setPlaying(false)
    }
  }, [autoScrollWithRecord])

  return {
    script, setScript, playing, toggle, reset, speed, setSpeed,
    fontSize, setFontSize, mirror, setMirror, direction, setDirection,
    offset, visible, setVisible, setRecordingActive, maxScroll, setMaxScroll,
  }
}

const BT_CAMERA_PREFIXES = ['GoPro', 'Insta360', 'DJI', 'Osmo', 'Canon', 'Sony', 'Ricoh', 'Theta', 'AKASO', 'Campark']

const FAKE_DEVICE_IDS = new Set(['default', 'communications'])

function uniqueCameras(cameras) {
  const byDeviceId = new Map()

  for (const cam of cameras) {
    if (!cam.deviceId || FAKE_DEVICE_IDS.has(cam.deviceId)) continue
    if (!byDeviceId.has(cam.deviceId)) byDeviceId.set(cam.deviceId, cam)
  }

  if (byDeviceId.size > 0) return Array.from(byDeviceId.values())

  const seen = new Set()
  return cameras.filter(cam => {
    const key = cam.groupId || cam.deviceId
    if (!key || seen.has(key)) return false
    seen.add(key)
    return true
  })
}

function getAssignedDeviceIds(metaMap, streamMap) {
  return new Set(
    Object.entries(metaMap)
      .filter(([slot, meta]) => streamMap[slot] && meta?.type === 'usb' && meta.deviceId)
      .map(([, meta]) => meta.deviceId),
  )
}

function delay(ms) {
  return new Promise(r => setTimeout(r, ms))
}

function isMjpegUrl(url) {
  const u = url.toLowerCase()
  return u.includes('/video') || u.includes('mjpeg') || u.includes('/cam') || u.endsWith('.mjpg')
}

function isHlsUrl(url) {
  return url.toLowerCase().includes('.m3u8')
}

async function createWifiStream(url) {
  if (isHlsUrl(url)) {
    throw new Error('Streams HLS (.m3u8) requieren un proxy o convertidor. Usa MJPEG o una URL de video directa.')
  }

  if (isMjpegUrl(url) || url.match(/:\d+\/(video|shot|stream)/i)) {
    return createMjpegStream(url)
  }

  return createVideoElementStream(url)
}

function createMjpegStream(url) {
  return new Promise((resolve, reject) => {
    const canvas = document.createElement('canvas')
    canvas.width = 1280
    canvas.height = 720
    const ctx = canvas.getContext('2d')
    const img = new Image()
    img.crossOrigin = 'anonymous'

    let stream = null

let rafId = null
let failed = false

const draw = () => {
  if (img.naturalWidth > 0) {
    if (canvas.width !== img.naturalWidth || canvas.height !== img.naturalHeight) {
      canvas.width = img.naturalWidth
      canvas.height = img.naturalHeight
    }
    ctx.drawImage(img, 0, 0)
  }
  rafId = requestAnimationFrame(draw)
}

img.onload = () => {
  if (!stream) {
    stream = canvas.captureStream(24)
    draw()
    resolve({
      stream,
      cleanup: () => {
        if (rafId) cancelAnimationFrame(rafId)
        img.src = ''
      },
    })
  }
}

img.onerror = () => {
  if (!stream && !failed) {
    failed = true
    reject(new Error('No se pudo conectar al stream WiFi. Verifica la IP y que la cámara esté en la misma red.'))
  }
}

    img.src = url
  })
}

async function createVideoElementStream(url) {
  const video = document.createElement('video')
  video.crossOrigin = 'anonymous'
  video.muted = true
  video.playsInline = true
  video.autoplay = true
  video.src = url

  await new Promise((resolve, reject) => {
    video.onloadedmetadata = resolve
    video.onerror = () => reject(new Error('URL de video no válida o inaccesible'))
    video.play().catch(reject)
  })

  const stream = video.captureStream()
  return {
    stream,
    cleanup: () => {
      video.pause()
      video.src = ''
      video.remove()
    },
  }
}

