function setupPwa() {
  if (!import.meta.env.PROD) return

  migrateServiceWorker().catch(() => {})

  try {
    const updateSW = registerSW({
      immediate: true,
      onNeedRefresh() {
        notifyPwaUpdateAvailable()
        setPwaUpdateHandler(updateSW)
      },
      onRegisteredSW(_url, registration) {
        registration?.update()
      },
    })
  } catch {
    /* SW opcional — la app funciona sin él */
  }
}

