.wbR { background: #ff5f57; } .wbY { background: #febc2e; } .wbG { background: #28c840; }
.brand { font-size: 13px; font-weight: 500; color: var(--text-secondary); }
.brand span { color: var(--accent); }
.topCenter { display: flex; align-items: center; gap: 8px; flex: 1; justify-content: center; }
