}
.recDot { width: 6px; height: 6px; border-radius: 50%; background: var(--red); animation: pulse-dot 1.2s infinite; }
.recTimer { font-variant-numeric: tabular-nums; letter-spacing: .03em; }
.liveViewers {
  display: flex; align-items: center; gap: 4px;
