}
@keyframes countdown-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.1); }
}

/* INIT OVERLAY */
.initOverlay {
  position: fixed; inset: 0; z-index: 999;
  background: rgba(5,5,8,.9);
  display: flex; align-items: center; justify-content: center;
}
.initCard {
