  border-radius: var(--radius-xl); padding: 36px 40px;
  text-align: center; max-width: 380px;
}
.initError {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; color: var(--red); background: var(--red-dim);
  border: 1px solid rgba(224,80,80,.3); border-radius: var(--radius-md);

  padding: 8px 12px; margin-top: 14px;
}

/* RESPONSIVE — tablet, iPad, móvil */
.mobileOnly { display: none; }

.panelBackdrop {
  display: none;
  position: fixed;
  top: calc(44px + env(safe-area-inset-top, 0px));
  right: 0;
  bottom: env(safe-area-inset-bottom, 0px);
  left: 48px;
  z-index: 180;
  background: rgba(0, 0, 0, 0.45);
  border: none;
  cursor: pointer;
  touch-action: manipulation;
}

.touchStudio .layout {
  grid-template-columns: 48px minmax(0, 1fr);
}

.touchStudio .panelRight {
  position: fixed;
  top: calc(44px + env(safe-area-inset-top, 0px));
  bottom: env(safe-area-inset-bottom, 0px);
  width: min(340px, 94vw);
  z-index: 190;
  right: 0;
  transform: none;
  transition: visibility 0.25s, opacity 0.25s;
  visibility: hidden;
  opacity: 0;

  pointer-events: none;
  box-shadow: -12px 0 32px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-height: 0;
}

.touchStudio .panelRightOpen {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
}

.touchStudio .panelBackdrop {
  display: block;
  left: 48px;
}

.touchStudio .panelMobileHead {
  display: flex;
}

.touchStudio .sidebarLeft {
  position: relative;
  z-index: 210;
}

@media (max-width: 1024px) {
  .layout {
    grid-template-columns: 48px 1fr;
  }

  .mobileOnly { display: flex; }

.topbar { position: relative; z-index: 200; }

.panelBackdrop {
  display: block;
  left: 48px;
}

.sidebarLeft {
  position: relative;
  z-index: 210;
}

.panelRight {
  position: fixed;
  top: calc(44px + env(safe-area-inset-top, 0px));
  bottom: env(safe-area-inset-bottom, 0px);
  width: min(340px, 94vw);
  z-index: 190;
  right: 0;
  transform: none;
  transition: visibility 0.25s, opacity 0.25s;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  box-shadow: -12px 0 32px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-height: 0;
}

.panelRightOpen {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;

  }

  .panelMobileHead {
    display: flex;
  }

  .iconBtn {
    width: 40px;
    height: 40px;
    flex-shrink: 0;
  }

  .topCenter { display: none; }
  .projectTag { max-width: 140px; }
}

@media (max-width: 768px) {
  .layout {
    grid-template-columns: 1fr;
    grid-template-rows: minmax(0, 1fr) auto;
  }

  .sidebarLeft {
    flex-direction: row;
    width: 100%;
